  {
    "id": "session-12-scyldgar-keep_title",
    "type": "header",
    "props": {
      "title": "Session 12 - Scyldgar Keep",
      "color": "gold",
      "size": "md",
      "audioLinks": "[\n  {\n    \"label\": \"12 - Scyldgar Keep.mp3\",\n    \"url\": \"/media/session-audio/souls-of-destiny/session-12-1WwmCUSoyysp0Q3GksVzc_KS_JN-rBQbj.mp3\",\n    \"sourceFileId\": \"1WwmCUSoyysp0Q3GksVzc_KS_JN-rBQbj\",\n    \"sourceFileName\": \"12 - Scyldgar Keep.mp3\",\n    \"sourceUrl\": \"https://drive.google.com/file/d/1WwmCUSoyysp0Q3GksVzc_KS_JN-rBQbj/view?usp=sharing\"\n  }\n]",
